import React, { useState, useEffect, useRef } from "react";
import { FlaskConical, Database, Activity, Sparkle, Eye, EyeOff } from "lucide-react";
import { useNavigate } from "react-router-dom";

const TEAL = "#00C2B5";
const DARK = "#0F172A";
const FONT = "'Geist', 'Inter', sans-serif";

/* ────────────────────────────────────────────────────────────────
   Background — the actual Figma-exported hex/network artwork,
   inlined as a data URI (compressed to WebP) so the artifact stays
   a single self-contained file.
   ──────────────────────────────────────────────────────────────── */
const LOGIN_BG_IMAGE = "data:image/webp;base64,";

function LoginBackground() {
  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        backgroundColor: "#030509",
        backgroundImage: `url(${LOGIN_BG_IMAGE})`,
        backgroundSize: "cover",
        backgroundPosition: "left center",
        backgroundRepeat: "no-repeat",
      }}
    />
  );
}
const LOGO_IMAGE = "data:image/png;base64,";

function LogoMark({ size = 87 }) {
  return (
    <img
      src={LOGO_IMAGE}
      alt="iNovaPath"
      width={size}
      height={size}
      style={{ width: size, height: size, borderRadius: "50%", display: "block" }}
    />
  );
}

/* ── Shared light-card input style ─────────────────────────────── */
const inputStyle = {
  width: "100%",
  height: "52px",
  borderRadius: "12px",
  background: "#fff",
  fontFamily: FONT,
  fontSize: "15px",
  color: DARK,
  border: "1px solid #E5E7EB",
  padding: "0 16px",
  boxSizing: "border-box",
  outline: "none",
  transition: "border-color 0.15s ease",
};

function FieldLabel({ children }) {
  return (
    <div
      style={{
        fontFamily: FONT,
        fontSize: "14px",
        fontWeight: 500,
        lineHeight: "18px",
        color: "#475569",
        marginBottom: "10px",
      }}
    >
      {children}
    </div>
  );
}

function ErrorText({ children }) {
  if (!children) return null;
  return (
    <div style={{ fontFamily: FONT, fontSize: "12px", color: "#ef4444", marginTop: "4px" }}>
      {children}
    </div>
  );
}

function LoginScreen({ onLoginSuccess }) {
  const [values, setValues] = useState({ username: "", password: "", remember: false });
  const [errors, setErrors] = useState({});
  const [touched, setTouched] = useState({});
  const [showPassword, setShowPassword] = useState(false);
  const [focused, setFocused] = useState(null);

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setValues((v) => ({ ...v, [name]: type === "checkbox" ? checked : value }));
  };

  const handleBlur = (e) => {
    setTouched((t) => ({ ...t, [e.target.name]: true }));
    setFocused(null);
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const nextErrors = {};
    if (!values.username) nextErrors.username = "Email is required";
    if (!values.password) nextErrors.password = "Password is required";

    if (!nextErrors.username && !nextErrors.password) {
      if (values.username === "Admin" && values.password === "Admin") {
        setErrors({});
        if (onLoginSuccess) onLoginSuccess();
        return;
      }
      nextErrors.password = "Invalid credentials";
    }
    setTouched({ username: true, password: true });
    setErrors(nextErrors);
  };

  const fieldBorder = (name) =>
    focused === name ? { borderColor: TEAL, borderWidth: "1px" } : {};

  return (
    <div
      style={{
        position: "relative",
        height: "100vh",
        overflow: "hidden",
        fontFamily: FONT,
        background: "#030509",
        display: "flex",
        flexDirection: "column",
      }}
    >
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Geist:wght@400;500;600;700;800&display=swap');
        * { box-sizing: border-box; }
        input::placeholder { color: #94A3B8; opacity: 1; font-family: ${FONT}; font-size: 15px; }
      `}</style>

      <LoginBackground />

      <div style={{ position: "relative", zIndex: 2, flex: 1, minHeight: 0, display: "flex" }}>
        {/* ── LEFT PANEL ───────────────────────────────────────── */}
        <div style={{ flex: "1 1 725px", position: "relative" }}>
          {/* branding */}
          <div
            style={{
              position: "absolute",
              top: "80px",
              left: "80px",
              display: "flex",
              alignItems: "center",
              gap: "16px",
            }}
          >
            <LogoMark size={87} />
            <div
              style={{
                color: "#fff",
                fontWeight: 700,
                fontSize: "40px",
                lineHeight: "100%",
                letterSpacing: "-0.02em",
                fontFamily: FONT,
              }}
            >
              iNovaPath
            </div>
          </div>

          {/* narrative */}
          <div
            style={{
              position: "absolute",
              left: "80px",
              top: "289.5px",
              width: "560px",
              display: "flex",
              flexDirection: "column",
              alignItems: "flex-start",
              gap: "40px",
            }}
          >
            <div style={{ display: "flex", flexDirection: "column", gap: "24px", width: "560px" }}>
              <div
                style={{
                  color: "#FFFFFF",
                  fontWeight: 700,
                  fontFamily: FONT,
                  fontSize: "40px",
                  lineHeight: "110%",
                  width: "560px",
                }}
              >
                Accelerated Drug Discovery with Gen AI
              </div>
              <div
                style={{
                  color: "#FFFFFF",
                  fontWeight: 400,
                  fontSize: "18px",
                  lineHeight: "160%",
                  fontFamily: FONT,
                  width: "520px",
                }}
              >
                The advanced iNovaPath designed for researchers to identify, validate, and
                simulate novel therapeutic candidates.
              </div>
            </div>

            {/* features row */}
            <div style={{ display: "flex", gap: "32px", width: "566px" }}>
              {[
                { Icon: FlaskConical, label: "AI-Powered Analysis", w: 179 },
                { Icon: Database, label: "10k+ Compounds", w: 158 },
                { Icon: Activity, label: "Real-time Insights", w: 165 },
              ].map(({ Icon, label, w }) => (
                <div
                  key={label}
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: "12px",
                    width: w,
                    height: "32px",
                  }}
                >
                  <div
                    style={{
                      width: 32,
                      height: 32,
                      borderRadius: "8px",
                      background: "rgba(255,255,255,0.1)",
                      border: "1px solid rgba(0,194,181,0.2)",
                      boxSizing: "border-box",
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                      flexShrink: 0,
                    }}
                  >
                    <Icon size={18} strokeWidth={2} color={TEAL} />
                  </div>
                  <div
                    style={{
                      fontFamily: FONT,
                      fontSize: "14px",
                      fontWeight: 500,
                      color: "#F8FAFC",
                      lineHeight: "18px",
                    }}
                  >
                    {label}
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* ── RIGHT PANEL ──────────────────────────────────────── */}
        <div
          style={{
            flex: "0 0 715px",
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            justifyContent: "center",
            padding: "80px",
          }}
        >
          <div style={{ position: "relative" }}>
            {/* decorative sparkle */}
            <Sparkle
              size={18}
              color="#00F5D4"
              fill="#00F5D4"
              style={{
                position: "absolute",
                top: "48px",
                left: "48px",
                transform: "rotate(90deg)",
                zIndex: 1,
              }}
            />

            {/* form card */}
            <div
              style={{
                width: "400px",
                background: "#fff",
                borderRadius: "16px",
                border: "1px solid #E5E7EB",
                padding: "40px",
                display: "flex",
                flexDirection: "column",
                gap: "48px",
                boxShadow: "0px 10px 28px -10px rgba(0,0,0,0.15)",
              }}
            >
              {/* header */}
              <div style={{ display: "flex", flexDirection: "column", gap: "12px" }}>
                <div
                  style={{
                    fontFamily: FONT,
                    fontWeight: 600,
                    fontSize: "32px",
                    lineHeight: "42px",
                    color: DARK,
                  }}
                >
                  Sign in to continue
                </div>
                <div
                  style={{
                    fontFamily: FONT,
                    fontWeight: 400,
                    fontSize: "16px",
                    lineHeight: "21px",
                    color: "#475569",
                  }}
                >
                  Enter your research credentials
                </div>
              </div>

              <form
                  onSubmit={handleSubmit}
                  style={{ display: "flex", flexDirection: "column", gap: "32px" }}
                >
                  <div style={{ display: "flex", flexDirection: "column", gap: "24px" }}>
                    {/* Email */}
                    <div>
                      <FieldLabel>Email Address</FieldLabel>
                      <input
                        id="username"
                        name="username"
                        placeholder="e.g. researcher@drp.inst"
                        value={values.username}
                        onChange={handleChange}
                        onFocus={() => setFocused("username")}
                        onBlur={handleBlur}
                        style={{
                          ...inputStyle,
                          ...(touched.username && errors.username
                            ? { borderColor: "#ef4444" }
                            : fieldBorder("username")),
                        }}
                      />
                      <ErrorText>{touched.username && errors.username}</ErrorText>
                    </div>

                    {/* Password */}
                    <div>
                      <FieldLabel>Password</FieldLabel>
                      <div style={{ position: "relative" }}>
                        <input
                          id="password"
                          name="password"
                          type={showPassword ? "text" : "password"}
                          value={values.password}
                          onChange={handleChange}
                          onFocus={() => setFocused("password")}
                          onBlur={handleBlur}
                          style={{
                            ...inputStyle,
                            paddingRight: "44px",
                            ...(touched.password && errors.password
                              ? { borderColor: "#ef4444" }
                              : fieldBorder("password")),
                          }}
                        />
                        <button
                          type="button"
                          onClick={() => setShowPassword((v) => !v)}
                          style={{
                            position: "absolute",
                            right: "12px",
                            top: "50%",
                            transform: "translateY(-50%)",
                            background: "none",
                            border: "none",
                            padding: 0,
                            cursor: "pointer",
                            display: "flex",
                            alignItems: "center",
                          }}
                          aria-label={showPassword ? "Hide password" : "Show password"}
                        >
                          {showPassword ? (
                            <EyeOff size={20} color="#94A3B8" />
                          ) : (
                            <Eye size={20} color="#94A3B8" />
                          )}
                        </button>
                      </div>
                      <ErrorText>{touched.password && errors.password}</ErrorText>
                    </div>
                  </div>

                  {/* remember + forgot */}
                  <div
                    style={{
                      display: "flex",
                      justifyContent: "space-between",
                      alignItems: "center",
                    }}
                  >
                    <label
                      style={{
                        display: "flex",
                        alignItems: "center",
                        gap: "10px",
                        cursor: "pointer",
                      }}
                    >
                      <input
                        type="checkbox"
                        name="remember"
                        checked={values.remember}
                        onChange={handleChange}
                        style={{
                          width: 18,
                          height: 18,
                          borderRadius: "4px",
                          accentColor: TEAL,
                          cursor: "pointer",
                        }}
                      />
                      <span
                        style={{
                          fontFamily: FONT,
                          fontSize: "14px",
                          fontWeight: 400,
                          lineHeight: "18px",
                          color: "#475569",
                        }}
                      >
                        Remember me
                      </span>
                    </label>
                    <a
                      href="#"
                      onClick={(e) => e.preventDefault()}
                      style={{
                        fontFamily: FONT,
                        fontSize: "14px",
                        fontWeight: 600,
                        lineHeight: "18px",
                        color: TEAL,
                        cursor: "pointer",
                        textDecoration: "none",
                      }}
                    >
                      Forgot password?
                    </a>
                  </div>

                  {/* submit */}
                  <button
                    type="submit"
                    style={{
                      height: "56px",
                      borderRadius: "12px",
                      background: TEAL,
                      boxShadow: "0px 10px 24px -10px rgba(0,188,212,0.4)",
                      fontFamily: FONT,
                      fontWeight: 600,
                      fontSize: "16px",
                      lineHeight: "21px",
                      color: "#fff",
                      border: "none",
                      cursor: "pointer",
                      width: "100%",
                    }}
                    onMouseEnter={(e) => (e.currentTarget.style.background = "#09ADAB")}
                    onMouseLeave={(e) => (e.currentTarget.style.background = TEAL)}
                  >
                    Sign In
                  </button>

                  <div
                    style={{
                      marginTop: "-16px",
                      fontFamily: FONT,
                      fontSize: "12px",
                      color: "#94A3B8",
                      textAlign: "center",
                    }}
                  >
                    Demo credentials: Admin / Admin
                  </div>
              </form>
            </div>
          </div>

          {/* footer */}
          <div
            style={{
              marginTop: "24px",
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              gap: "8px",
            }}
          >
            <div style={{ fontFamily: FONT, fontSize: "12px", color: "rgba(255,255,255,0.32)" }}>
              © 2026 iNovaPath Powered by Gen AI.
            </div>
            <div style={{ display: "flex", gap: "20px" }}>
              {["Help Center", "Privacy Policy", "Terms of Service"].map((text) => (
                <a
                  key={text}
                  href="#"
                  onClick={(e) => e.preventDefault()}
                  style={{
                    fontFamily: FONT,
                    fontSize: "12px",
                    color: "rgba(255,255,255,0.38)",
                    textDecoration: "none",
                  }}
                >
                  {text}
                </a>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

const SPLASH_FONT = "'Inter', sans-serif";
const DURATION_MS = 6000; // shortened for preview — original spec used 60000 for screen recording

// Soft-but-visible edge via multi-stop gradient — NO CSS blur.
// Every circle keeps a clean, distinguishable boundary like the reference.
const glowGradient = (rgb, peak) => `radial-gradient(circle at 42% 40%,
  rgba(${rgb}, ${peak})        0%,
  rgba(${rgb}, ${peak * 0.85}) 55%,
  rgba(${rgb}, ${peak * 0.55}) 80%,
  rgba(${rgb}, ${peak * 0.20}) 94%,
  rgba(${rgb}, 0)              100%)`;

/* ── Circle definitions (7 total, matched to Figma) ────────────────
   ring-1        → STATIC 520px center circle. Visible solid edge. No motion.
   bg-glow-main  → 1100px huge soft background glow. Bounces.
   glow-tl-1/2, glow-top-right, glow-bottom-right, glow-mid-left
                 → the 5 remaining corner/edge glows. Bounce.
   NONE of these use CSS blur — softness comes only from the gradient.
──────────────────────────────────────────────────────────────────*/
const CIRCLES = [
  // Static center circle — vertical gradient, clearly visible, never moves
  {
    id: "ring-1", d: 520, static: true,
    fill: "linear-gradient(180deg, #00C2B5 0%, #005C56 100%)",
    border: "1px solid rgba(0,194,181,0.35)",
    op: 0.88,
    anim: "drp-pulse-inner 4s ease-in-out infinite",
  },

  // Bouncing background glows — sized to match Figma, no blur
  { id: "bg-glow-main",      d: 1100, rgb: "10,191,188",  ix: 10, iy:  0, vx:  0.35, vy:  0.30, peak: 0.45 },
  { id: "glow-mid-left",     d: 300,  rgb: "10,191,188",  ix:  6, iy: 50, vx:  0.60, vy:  0.42, peak: 0.40 },
  { id: "glow-bottom-right", d: 260,  rgb: "10,191,188",  ix: 72, iy: 64, vx:  0.55, vy: -0.46, peak: 0.40 },
  { id: "glow-top-right",    d: 240,  rgb: "139,92,246",  ix: 71, iy: 10, vx: -0.50, vy:  0.50, peak: 0.40 },
  { id: "glow-tl-1",         d: 220,  rgb: "10,191,188",  ix:  5, iy: 10, vx:  0.55, vy:  0.50, peak: 0.45 },
  { id: "glow-tl-2",         d: 160,  rgb: "139,92,246",  ix:  5, iy: 30, vx: -0.60, vy:  0.55, peak: 0.40 },
];

const styles = `
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');

  /* Center circle — gentle glow breathe */
  @keyframes drp-pulse-inner {
    0%, 100% { opacity: 0.80; box-shadow: 0 0 80px 28px rgba(10,191,188,0.18); }
    50%      { opacity: 0.95; box-shadow: 0 0 140px 58px rgba(10,191,188,0.32); }
  }

  /* Three loading dots */
  @keyframes drp-dot {
    0%, 80%, 100% { transform: scale(0.55); opacity: 0.35; }
    40%           { transform: scale(1.0);  opacity: 1.0;  }
  }

  /* Content card fade-in */
  @keyframes drp-fadein {
    from { opacity: 0; transform: translateY(18px); }
    to   { opacity: 1; transform: translateY(0);    }
  }

  /* Progress bar fills left→right over DURATION_MS */
  @keyframes drp-progress {
    from { width: 0%;   }
    to   { width: 100%; }
  }
`;

function SplashScreen() {
  const navigate = useNavigate();
  const refs = useRef([]);
  const state = useRef([]);
  const raf = useRef(null);
  const [done, setDone] = useState(false);

  /* ── Auto-advance when the progress bar finishes ─────────────────── */
  useEffect(() => {
    const t = setTimeout(() => {
      setDone(true);
      navigate('/welcome');
    }, DURATION_MS);
    return () => clearTimeout(t);
  }, [navigate]);

  /* ── Bouncing physics (id 0 static center circle is skipped) ────── */
  useEffect(() => {
    const vw = window.innerWidth;
    const vh = window.innerHeight;

    state.current = CIRCLES.map((c) => ({
      id: c.id,
      d: c.d,
      static: !!c.static,
      x: c.static ? 0 : (c.ix / 100) * vw,
      y: c.static ? 0 : (c.iy / 100) * vh,
      vx: c.vx ?? 0,
      vy: c.vy ?? 0,
    }));

    const tick = () => {
      const cs = state.current;
      for (let i = 0; i < cs.length; i++) {
        const c = cs[i];
        if (c.static) continue;

        c.x += c.vx;
        c.y += c.vy;

        // Bounce off all four walls
        if (c.x <= 0) { c.x = 0; c.vx = Math.abs(c.vx); }
        if (c.x >= vw - c.d) { c.x = vw - c.d; c.vx = -Math.abs(c.vx); }
        if (c.y <= 0) { c.y = 0; c.vy = Math.abs(c.vy); }
        if (c.y >= vh - c.d) { c.y = vh - c.d; c.vy = -Math.abs(c.vy); }

        // GPU-composited update — no layout thrash
        const el = refs.current[i];
        if (el) el.style.transform = `translate3d(${c.x}px,${c.y}px,0)`;
      }
      raf.current = requestAnimationFrame(tick);
    };

    raf.current = requestAnimationFrame(tick);
    return () => {
      if (raf.current) cancelAnimationFrame(raf.current);
    };
  }, []);

  /* ── Render ───────────────────────────────────────────────────── */
  return (
    <>
      <style>{styles}</style>

      <div
        style={{
          position: "fixed",
          inset: 0,
          overflow: "hidden",
          background: "linear-gradient(135deg, #1E1B4B 0%, #2D2B55 55%, #1A2045 100%)",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        {/* ── Circles ──────────────────────────────────────────────── */}
        {CIRCLES.map((c, i) => {
          const vw = typeof window !== "undefined" ? window.innerWidth : 1440;
          const vh = typeof window !== "undefined" ? window.innerHeight : 1024;
          const initX = ((c.ix ?? 0) / 100) * vw;
          const initY = ((c.iy ?? 0) / 100) * vh;
          const isStatic = !!c.static;

          const background = isStatic ? c.fill : glowGradient(c.rgb, c.peak);

          return (
            <div
              key={c.id}
              ref={(el) => {
                refs.current[i] = el;
              }}
              style={{
                position: "absolute",
                width: c.d,
                height: c.d,
                borderRadius: "50%",
                background,
                opacity: c.op,
                ...(c.border && { border: c.border }),
                willChange: isStatic ? "opacity, box-shadow" : "transform",
                ...(isStatic
                  ? {
                      top: "50%",
                      left: "50%",
                      marginTop: -(c.d / 2),
                      marginLeft: -(c.d / 2),
                      animation: c.anim,
                    }
                  : { top: 0, left: 0, transform: `translate3d(${initX}px,${initY}px,0)` }),
              }}
            />
          );
        })}

        {/* Vignette — draws eye to centre */}
        <div
          style={{
            position: "absolute",
            inset: 0,
            zIndex: 1,
            pointerEvents: "none",
            background: "radial-gradient(ellipse at 50% 50%, transparent 30%, rgba(18,16,55,0.68) 100%)",
          }}
        />

        {/* ── Centre content — no card, sits directly on ring-1 ──────── */}
        <div
          style={{
            position: "relative",
            zIndex: 10,
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            gap: "24px",
            animation: "drp-fadein 1s cubic-bezier(0.22,1,0.36,1) both 0.25s",
            width: "373px",
          }}
        >
          {/* Logo — real 87×87 round export */}
          <LogoMark size={87} />

          {/* Title + subtitle */}
          <div style={{ textAlign: "center" }}>
            <div
              style={{
                fontFamily: SPLASH_FONT,
                fontWeight: 700,
                fontSize: "28px",
                lineHeight: "100%",
                color: "#FFFFFF",
                width: "373px",
              }}
            >
              iNovaPath
            </div>
            <div
              style={{
                fontFamily: SPLASH_FONT,
                fontWeight: 400,
                fontSize: "14px",
                lineHeight: "17px",
                color: "rgba(255,255,255,0.6)",
                textShadow: "0px 4px 10px rgba(0,0,0,0.2)",
                width: "257px",
                margin: "8px auto 0",
              }}
            >
              {done ? "Ready — redirecting to your workspace…" : "Preparing your research environment..."}
            </div>
          </div>

          {/* Progress bar — fills over DURATION_MS */}
          <div
            style={{
              width: "210px",
              height: "2px",
              background: "rgba(255,255,255,0.12)",
              borderRadius: "2px",
              overflow: "hidden",
            }}
          >
            <div
              style={{
                height: "100%",
                borderRadius: "2px",
                background: TEAL,
                width: done ? "100%" : "0%",
                boxShadow: `0 0 8px ${TEAL}`,
                animation: `drp-progress ${DURATION_MS}ms linear forwards`,
              }}
            />
          </div>

          {/* spinner-container: 3 dots */}
          {!done && (
            <div style={{ display: "flex", alignItems: "center", gap: "4px" }}>
              {[0, 0.2, 0.4].map((delay, idx) => (
                <div
                  key={idx}
                  style={{
                    width: 8,
                    height: 8,
                    borderRadius: "50%",
                    background: TEAL,
                    animation: `drp-dot 1.4s ease-in-out ${delay}s infinite`,
                  }}
                />
              ))}
            </div>
          )}
        </div>
      </div>
    </>
  );
}

/* ══════════════════  Export SplashScreen ════════════════════════════
   Integrated with React Router navigation
   ══════════════════════════════════════════════════════════════════ */
export default SplashScreen;